/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#ifdef CONFIG_SCHED_EVENTS

#include <nuttx/event.h>
#include <nuttx/sched.h>
#include <nuttx/irq.h>
#include "event.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: nxevent_wake_waiter
 *
 * Description:
 *   Wake up a waiter if the posted events match its wait condition.
 *
 * Input Parameters:
 *   event - Pointer to the event group
 *   events - Events that were posted
 *   flags - Post flags
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void nxevent_wake_waiter(FAR nxevent_t *event, uint32_t events,
                                int flags)
{
  FAR nxevent_waiter_t *waiter = event->waiters;
  FAR nxevent_waiter_t *prev = NULL;

  while (waiter != NULL)
    {
      FAR nxevent_waiter_t *next = waiter->next;
      uint32_t matched_events;

      /* Check if this waiter's condition is satisfied */

      if (waiter->flags & NXEVENT_WAIT_ALL)
        {
          /* Wait for ALL events */
          matched_events = (events & waiter->events);
          if (matched_events == waiter->events)
            {
              /* All requested events are present */
              *waiter->received = matched_events;

              /* Remove waiter from list */
              if (prev == NULL)
                {
                  event->waiters = next;
                }
              else
                {
                  prev->next = next;
                }

              /* Wake up the task */
              nxsem_wait_irq(waiter->tcb);
              continue;
            }
        }
      else
        {
          /* Wait for ANY event */
          matched_events = (events & waiter->events);
          if (matched_events != 0)
            {
              /* At least one requested event is present */
              *waiter->received = matched_events;

              /* Remove waiter from list */
              if (prev == NULL)
                {
                  event->waiters = next;
                }
              else
                {
                  prev->next = next;
                }

              /* Wake up the task */
              nxsem_wait_irq(waiter->tcb);
              continue;
            }
        }

      prev = waiter;
      waiter = next;
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: nxevent_post
 *
 * Description:
 *   Post events to an event group.
 *
 * Input Parameters:
 *   event - Pointer to the event group
 *   events - Event bits to post
 *   flags - Post flags (reserved for future use)
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

void nxevent_post(FAR nxevent_t *event, uint32_t events, int flags)
{
  irqstate_t flags_state;

  flags_state = enter_critical_section();

  /* Set the events */
  event->events |= events;

  /* Wake up any waiters that match these events */
  nxevent_wake_waiter(event, events, flags);

  leave_critical_section(flags_state);
}

#endif /* CONFIG_SCHED_EVENTS */
EOF"}

